"""
@package mocaxpy.MocaxException
MocaxException module.

Exports the MocaxException class.
"""

import mocaxpy.MocaxCInterface

import sys

if sys.version_info.major >= 3:
    long = int


class MocaxException(Exception):
    """
    A Mocax exception.
    """

    def __init__(self, error_number, message=None):
        """
        Constructs an exception.

        @param[in] error_number The Mocax error code associated to this exception. Allowed types: @c int, @c long
        @param[in] message An optional message for the exception. If None is passed as this argument,
                   then the default message for the Mocax error code will be used.
                   Allowed types: @c str, @c None
        """

        if isinstance(error_number, str):
            error_number = int(float(error_number))
        if not isinstance(error_number, (int, long)):
            raise TypeError("error_number only allows integer values or string values parsable as integers")

        self.__errorNumber = error_number
        if message is None:
            self.__message = mocaxpy.MocaxCInterface.mocax_error_description(self.__errorNumber)
        else:
            self.__message = str(message)

    def get_error_number(self):
        """
        Gets the error code associated to the exception.

        @return The error number of this exception.
                Return type: @c int

        """
        return self.__errorNumber

    def __str__(self):
        """
        String representation method.

        @return A string representation of this exception.
                Return type: @c str
        """
        return self.__message
